package com.chatboxcontroller;

import java.util.function.Consumer;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;

/**
 * Keeps an empty band at the top of the chat messages area by moving the top of the message area and its scrollbar
 * down and shrinking them by the same amount. Before every frame is drawn it re-reads the widgets, so a reload by the
 * game or a change by another plugin is never stacked on top of its own change, and never shows for a frame.
 * <p>
 * Choice: restore() leaves a widget alone when it already holds its base values, so a pad of 0 costs nothing.
 */
final class ChatSpace
{
	static final int LINE_HEIGHT = 14;
	/** Two whole lines: the least the message area keeps. */
	static final int MIN_VISIBLE = 2 * LINE_HEIGHT + 2;

	enum Layout
	{
		FIXED, RESIZABLE_CLASSIC, RESIZABLE_MODERN
	}

	/** What the plugin knows about one widget. */
	private static final class Slot
	{
		private final int id;
		private Widget widget;
		private int baseY;
		private int baseHeight;
		private boolean applied;
		private int appliedY;
		private int appliedHeight;

		private Slot(int id)
		{
			this.id = id;
		}

		private void forget()
		{
			widget = null;
			applied = false;
		}
	}

	private final Client client;
	/** Where each change is told, for a developer-mode client; a no-op otherwise. */
	private final Consumer<String> trace;
	private final Slot[] slots =
	{
		new Slot(InterfaceID.Chatbox.SCROLLAREA),
		new Slot(InterfaceID.Chatbox.CHATSCROLLBAR)
	};

	ChatSpace(Client client, Consumer<String> trace)
	{
		this.client = client;
		this.trace = trace;
	}

	static int padPixels(int lines)
	{
		return Math.max(0, lines) * LINE_HEIGHT;
	}

	static Layout layout(Client client)
	{
		if (!client.isResized())
		{
			return Layout.FIXED;
		}
		return client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1
			? Layout.RESIZABLE_MODERN : Layout.RESIZABLE_CLASSIC;
	}

	/**
	 * How many pixels to add to a pad so the message area holds whole lines and nothing of the line above them: the
	 * game stacks 14 px lines up from 2 px above the area's bottom, so a height of 14k + 2 still shows a 2 px strip of
	 * the line above (its descenders and icons, specks in the blank band - the client test of 2026-11-25); a height of
	 * 14k hides it and trims only the top 2 px of the first line, where text has no ink. Nothing is added when it
	 * would leave less than one whole line.
	 */
	static int toWholeLines(int visible)
	{
		final int rest = Math.floorMod(visible, LINE_HEIGHT);
		return visible - rest >= LINE_HEIGHT ? rest : 0;
	}

	/**
	 * @param wantedPad the blank band's height in pixels; it is made up to 13 px taller when needed so the top message
	 * is never cut in half
	 */
	void update(int wantedPad)
	{
		boolean changed = false;
		for (Slot slot : slots)
		{
			final Widget w = client.getWidget(slot.id);
			if (w == null)
			{
				slot.forget();
				continue;
			}
			final int y = w.getOriginalY();
			final int height = w.getOriginalHeight();
			if (w != slot.widget || !slot.applied)
			{
				slot.widget = w;
				slot.baseY = y;
				slot.baseHeight = height;
			}
			else
			{
				// Each value on its own: the game's toplevel_chatbox_background puts the top back to 0 and leaves the
				// height, so taking both as a new base would shrink the area again on every redraw.
				if (y != slot.appliedY)
				{
					slot.baseY = y;
				}
				if (height != slot.appliedHeight)
				{
					slot.baseHeight = height;
				}
			}
			if (w.getYPositionMode() != WidgetPositionMode.ABSOLUTE_TOP || w.getHeightMode() != WidgetSizeMode.MINUS)
			{
				slot.applied = false;
				continue;
			}
			final Widget parent = w.getParent();
			final int room = parent == null ? 0 : Math.max(0, parent.getHeight() - slot.baseHeight - MIN_VISIBLE);
			int pad = Math.max(0, Math.min(wantedPad, room));
			if (pad > 0 && parent != null)
			{
				pad += toWholeLines(parent.getHeight() - slot.baseHeight - pad);
			}
			final int targetY = slot.baseY + pad;
			final int targetHeight = slot.baseHeight + pad;
			if (y != targetY || height != targetHeight)
			{
				trace.accept(String.format("widget %d: was (%d, %d), base (%d, %d), set (%d, %d), parent height %d",
					slot.id & 0xFFFF, y, height, slot.baseY, slot.baseHeight, targetY, targetHeight,
					parent == null ? -1 : parent.getHeight()));
				w.setOriginalY(targetY);
				w.setOriginalHeight(targetHeight);
				relayout(w, slot.id == InterfaceID.Chatbox.CHATSCROLLBAR);
				// Only a new height changes how the lines are laid out; a top put back needs no rebuild.
				changed |= height != targetHeight;
			}
			slot.applied = true;
			slot.appliedY = targetY;
			slot.appliedHeight = targetHeight;
		}
		if (changed)
		{
			trace.accept("refreshChat");
			client.refreshChat();
		}
	}

	void restore()
	{
		boolean changed = false;
		for (Slot slot : slots)
		{
			if (slot.applied)
			{
				final Widget w = client.getWidget(slot.id);
				if (w != null && w == slot.widget
					&& w.getOriginalY() == slot.appliedY && w.getOriginalHeight() == slot.appliedHeight
					&& (slot.appliedY != slot.baseY || slot.appliedHeight != slot.baseHeight))
				{
					w.setOriginalY(slot.baseY);
					w.setOriginalHeight(slot.baseHeight);
					relayout(w, slot.id == InterfaceID.Chatbox.CHATSCROLLBAR);
					changed = true;
				}
			}
			slot.forget();
		}
		if (changed)
		{
			client.refreshChat();
		}
	}

	/**
	 * Recomputes a widget's bounds and then its dynamic children's: the scrollbar's arrows, track and dragger are
	 * made by the game's scrollbar_vertical script with sizes and positions relative to the bar (minus, abs_bottom), and
	 * a revalidate of the bar alone left them laid out for the old height (the client test of 2026-11-25). Only the
	 * bar's children: the message area holds up to 2,000 line widgets that the chat rebuild places itself.
	 */
	private static void relayout(Widget w, boolean children)
	{
		w.revalidate();
		if (!children)
		{
			return;
		}
		final Widget[] parts = w.getDynamicChildren();
		if (parts != null)
		{
			for (Widget child : parts)
			{
				if (child != null)
				{
					child.revalidate();
				}
			}
		}
	}
}

package com.chatboxcontroller;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

/**
 * The plugin's settings. Flat on purpose: every item is declared here and this interface extends {@link Config}
 * alone, because RuneLite stores defaults only for the methods declared on the interface it is given. The group and
 * the keys are frozen at first release; renaming one silently discards every player's setting.
 */
@ConfigGroup(ChatboxControllerConfig.GROUP)
public interface ChatboxControllerConfig extends Config
{
	String GROUP = "chatbox-controller";

	@ConfigItem(
		keyName = "topLines",
		name = "Blank lines at top",
		description = "How many chat lines to keep empty at the top of the chatbox (up to 6, so two lines of chat always show)",
		position = 1
	)
	@Range(min = 0, max = 6)
	default int topLines()
	{
		return 2;
	}

	@ConfigItem(
		keyName = "fixedMode",
		name = "In fixed mode",
		description = "Keep the blank lines in the fixed layout",
		position = 2
	)
	default boolean fixedMode()
	{
		return true;
	}

	@ConfigItem(
		keyName = "resizableClassic",
		name = "In resizable classic",
		description = "Keep the blank lines in the resizable classic layout",
		position = 3
	)
	default boolean resizableClassic()
	{
		return true;
	}

	@ConfigItem(
		keyName = "resizableModern",
		name = "In resizable modern",
		description = "Keep the blank lines in the resizable modern layout",
		position = 4
	)
	default boolean resizableModern()
	{
		return true;
	}
}

package com.chatboxcontroller;

import com.google.inject.Provides;
import javax.inject.Inject;
import javax.inject.Named;
import net.runelite.api.Client;
import net.runelite.api.events.BeforeRender;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.RuneLiteProperties;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * 2h Chatbox Controller: keeps blank lines at the top of the chatbox (ChatSpace, before every frame is drawn).
 * It has no sidebar panel: its settings are RuneLite's. Shutting it down puts the chatbox back.
 */
@PluginDescriptor(
	name = "2h Chatbox Controller",
	internalName = "chatbox-controller",
	description = "Keeps blank lines at the top of the chatbox so infoboxes have room, in fixed and resizable layouts (v" + Version.CURRENT + ")",
	tags = {"chat", "chatbox", "infobox", "padding", "space", "fixed", "layout", "2h"}
)
public class ChatboxControllerPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(ChatboxControllerPlugin.class);

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatboxControllerConfig config;

	@Inject
	@Named("developerMode")
	private boolean developerMode;

	private ChatSpace space;
	/** How many changes the developer-mode trace has seen: the first 60 are logged, then every 500th. */
	private int traced;

	@Provides
	ChatboxControllerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ChatboxControllerConfig.class);
	}

	@Override
	protected void startUp()
	{
		traced = 0;
		space = new ChatSpace(client, developerMode ? this::trace : line ->
		{
		});
		log.info("2h Chatbox Controller {} started on RuneLite {}", Version.CURRENT, RuneLiteProperties.getVersion());
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		if (space == null)
		{
			return;
		}
		final boolean on = enabledFor(ChatSpace.layout(client));
		space.update(on ? ChatSpace.padPixels(config.topLines()) : 0);
	}

	private void trace(String line)
	{
		traced++;
		if (traced <= 60 || traced % 500 == 0)
		{
			log.info("chatbox change {} (layout {}): {}", traced, ChatSpace.layout(client), line);
		}
	}

	private boolean enabledFor(ChatSpace.Layout layout)
	{
		switch (layout)
		{
			case FIXED:
				return config.fixedMode();
			case RESIZABLE_MODERN:
				return config.resizableModern();
			default:
				return config.resizableClassic();
		}
	}

	@Override
	protected void shutDown()
	{
		if (space != null)
		{
			final ChatSpace leaving = space;
			space = null;
			clientThread.invoke(leaving::restore);
		}
	}
}

package com.chatboxcontroller;

/**
 * The one place the plugin's version is written. The descriptor's description, the settings menu's header and the
 * start-up log line read it; the frame test checks it against {@code version=} in runelite-plugin.properties.
 */
public final class Version
{
	/** The version this build ships as, {@code major.minor.patch}. */
	public static final String CURRENT = "1.0.0";

	private Version()
	{
	}
}

package com.chatboxcontroller;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ChatSpaceTest
{
	private static final int AREA = InterfaceID.Chatbox.SCROLLAREA;
	private static final int BAR = InterfaceID.Chatbox.CHATSCROLLBAR;

	private Client client;
	private Widget parent;
	private Widget area;
	private Widget bar;
	private ChatSpace space;

	/** A widget whose original values the setters change. */
	private static Widget widget(Widget parent, int ymode, int heightMode)
	{
		final Widget w = Mockito.mock(Widget.class);
		final int[] v = {0, 16};
		when(w.getOriginalY()).thenAnswer(i -> v[0]);
		when(w.getOriginalHeight()).thenAnswer(i -> v[1]);
		Mockito.doAnswer(i ->
		{
			v[0] = i.getArgument(0);
			return w;
		}).when(w).setOriginalY(anyInt());
		Mockito.doAnswer(i ->
		{
			v[1] = i.getArgument(0);
			return w;
		}).when(w).setOriginalHeight(anyInt());
		when(w.getYPositionMode()).thenReturn(ymode);
		when(w.getHeightMode()).thenReturn(heightMode);
		when(w.getParent()).thenReturn(parent);
		return w;
	}

	@Before
	public void setUp()
	{
		client = Mockito.mock(Client.class);
		parent = Mockito.mock(Widget.class);
		when(parent.getHeight()).thenReturn(130);
		area = widget(parent, 0, 1);
		bar = widget(parent, 0, 1);
		when(client.getWidget(AREA)).thenReturn(area);
		when(client.getWidget(BAR)).thenReturn(bar);
		space = new ChatSpace(client, line ->
		{
		});
	}

	private static void assertValues(Widget w, int y, int height)
	{
		assertEquals(y, w.getOriginalY());
		assertEquals(height, w.getOriginalHeight());
	}

	@Test
	public void padPixels()
	{
		assertEquals(28, ChatSpace.padPixels(2));
		assertEquals(0, ChatSpace.padPixels(0));
		assertEquals(42, ChatSpace.padPixels(3));
		assertEquals(0, ChatSpace.padPixels(-1));
	}

	@Test
	public void appliesPadToBothWidgets()
	{
		space.update(28);
		assertValues(area, 30, 46);
		assertValues(bar, 30, 46);
		verify(area, times(1)).revalidate();
		verify(bar, times(1)).revalidate();
		verify(client, times(1)).refreshChat();
	}

	@Test
	public void steadyStateDoesNothing()
	{
		space.update(28);
		Mockito.clearInvocations(client, area, bar);
		space.update(28);
		verify(area, never()).setOriginalY(anyInt());
		verify(area, never()).setOriginalHeight(anyInt());
		verify(bar, never()).setOriginalY(anyInt());
		verify(bar, never()).setOriginalHeight(anyInt());
		verify(area, never()).revalidate();
		verify(bar, never()).revalidate();
		verify(client, never()).refreshChat();
	}

	@Test
	public void gameResetIsReappliedFromNewBase()
	{
		space.update(28);
		area.setOriginalY(0);
		area.setOriginalHeight(16);
		space.update(28);
		assertValues(area, 30, 46);
	}

	/** The client test of 2026-11-25: the game puts the top back to 0 and keeps the height; nothing may stack. */
	@Test
	public void topPutBackAloneDoesNotShrinkTheArea()
	{
		space.update(14);
		for (int i = 0; i < 5; i++)
		{
			area.setOriginalY(0);
			bar.setOriginalY(0);
			space.update(14);
		}
		assertValues(area, 16, 32);
		assertValues(bar, 16, 32);
		verify(client, times(1)).refreshChat();
	}

	@Test
	public void changingThePadUsesTheBase()
	{
		space.update(28);
		space.update(42);
		assertValues(area, 44, 60);
		assertValues(bar, 44, 60);
	}

	@Test
	public void zeroPadPutsBaseBack()
	{
		space.update(28);
		Mockito.clearInvocations(client);
		space.update(0);
		assertValues(area, 0, 16);
		assertValues(bar, 0, 16);
		verify(client, times(1)).refreshChat();
	}

	@Test
	public void padIsClamped()
	{
		when(parent.getHeight()).thenReturn(60);
		// 60 - 16 leaves 44: two lines (30) stay, so the pad is 14, then 2 more hide the strip above them
		space.update(100);
		assertValues(area, 16, 32);
		assertValues(bar, 16, 32);
	}

	@Test
	public void nullWidgetIsSkippedAndNewObjectTakesItsOwnBase()
	{
		when(client.getWidget(AREA)).thenReturn(null);
		when(client.getWidget(BAR)).thenReturn(null);
		space.update(28);
		verify(client, never()).refreshChat();
		final Widget fresh = widget(parent, 0, 1);
		when(client.getWidget(AREA)).thenReturn(fresh);
		space.update(28);
		assertValues(fresh, 30, 46);
	}

	@Test
	public void otherModesAreLeftAlone()
	{
		final Widget otherHeight = widget(parent, 0, 0);
		final Widget otherY = widget(parent, 2, 1);
		when(client.getWidget(AREA)).thenReturn(otherHeight);
		when(client.getWidget(BAR)).thenReturn(otherY);
		space.update(28);
		verify(otherHeight, never()).setOriginalY(anyInt());
		verify(otherHeight, never()).setOriginalHeight(anyInt());
		verify(otherY, never()).setOriginalY(anyInt());
		verify(otherY, never()).setOriginalHeight(anyInt());
	}

	@Test
	public void restorePutsBaseBack()
	{
		space.restore();
		verify(client, never()).refreshChat();
		space.update(28);
		Mockito.clearInvocations(client);
		space.restore();
		assertValues(area, 0, 16);
		assertValues(bar, 0, 16);
		verify(client, times(1)).refreshChat();
	}

	@Test
	public void restoreSkipsAWidgetChangedSinceByOthers()
	{
		space.update(28);
		area.setOriginalY(5);
		area.setOriginalHeight(20);
		space.restore();
		assertValues(area, 5, 20);
		assertValues(bar, 0, 16);
	}

	@Test
	public void layoutDetection()
	{
		when(client.isResized()).thenReturn(false);
		assertEquals(ChatSpace.Layout.FIXED, ChatSpace.layout(client));
		when(client.isResized()).thenReturn(true);
		when(client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT)).thenReturn(1);
		assertEquals(ChatSpace.Layout.RESIZABLE_MODERN, ChatSpace.layout(client));
		when(client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT)).thenReturn(0);
		assertEquals(ChatSpace.Layout.RESIZABLE_CLASSIC, ChatSpace.layout(client));
	}

	@Test
	public void configDefaultsAndKeys()
	{
		final ChatboxControllerConfig config = Mockito.mock(ChatboxControllerConfig.class, Mockito.CALLS_REAL_METHODS);
		assertEquals(2, config.topLines());
		assertEquals(true, config.fixedMode());
		assertEquals(true, config.resizableClassic());
		assertEquals(true, config.resizableModern());
	}

	/** The client test of 2026-11-25: a band of 1 line and 7 px cut the top message in half; a chat height that is
	 * not whole lines (resizable) does the same. */
	@Test
	public void wholeLinesHidesTheSliver()
	{
		// parent 130, base 16: 21 px leaves 93 = 6 lines and 9 px, so the band grows by 9 to 30.
		space.update(21);
		assertValues(area, 30, 46);
		assertValues(bar, 30, 46);
		// a pad of whole lines is left as it is
		space.update(28);
		assertValues(area, 30, 46);
	}

	@Test
	public void toWholeLines()
	{
		// 114 = 8 lines and the game's 2 px: the 2 px strip goes too
		assertEquals(2, ChatSpace.toWholeLines(114));
		assertEquals(9, ChatSpace.toWholeLines(93));
		assertEquals(1, ChatSpace.toWholeLines(127));
		assertEquals(0, ChatSpace.toWholeLines(28));
		assertEquals(1, ChatSpace.toWholeLines(29));
		// never below one whole line
		assertEquals(0, ChatSpace.toWholeLines(13));
	}

	@Test
	public void wholeLinesAddsNothingWithoutAPad()
	{
		when(parent.getHeight()).thenReturn(125);
		space.update(0);
		assertValues(area, 0, 16);
		verify(client, never()).refreshChat();
	}

	/** The client test of 2026-11-25: the scrollbar's arrows stayed where the old height put them. */
	@Test
	public void scrollbarPartsAreLaidOutAgain()
	{
		final Widget arrow = Mockito.mock(Widget.class);
		final Widget track = Mockito.mock(Widget.class);
		final Widget line = Mockito.mock(Widget.class);
		when(bar.getDynamicChildren()).thenReturn(new Widget[] {track, null, arrow});
		when(area.getDynamicChildren()).thenReturn(new Widget[] {line});
		space.update(28);
		// the message area's lines are placed by the chat rebuild, never one by one
		verify(line, never()).revalidate();
		verify(arrow, times(1)).revalidate();
		verify(track, times(1)).revalidate();
		Mockito.clearInvocations(arrow, track);
		space.restore();
		verify(arrow, times(1)).revalidate();
		verify(track, times(1)).revalidate();
	}
}

package com.chatboxcontroller;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Standalone runner: boots RuneLite in developer mode with 2h Chatbox Controller injected. This is what {@code gradlew run}
 * starts. It lives in the test source set, so the packaged jar never holds it, and it has no {@code @Test} method,
 * so the test task skips it. {@code ExternalPluginManager.loadBuiltin} needs assertions on, which the run task passes.
 */
public class ChatboxControllerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ChatboxControllerPlugin.class);
		RuneLite.main(args);
	}
}
